/* Renders site/skills.json — generated by site/build.py from the repository.
 * Do not hardcode skills here: add a SKILL.md folder and CI regenerates the data.
 */

const AGENTS = [
  { name: "Claude Code", path: "~/.claude/skills/" },
  { name: "Qoder Desktop", path: "~/.qoder/skills/" },
  { name: "OpenCode", path: "~/.config/opencode/skills/" },
  { name: "ZCode (Z.ai)", path: "~/.zcode/skills/" },
  { name: "Google Antigravity", path: "~/.gemini/antigravity/skills/" },
  { name: "OpenAI Codex", path: "~/.agents/skills/" },
];

function el(tag, cls, html) {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (html != null) n.innerHTML = html;
  return n;
}

function esc(s) {
  return (s || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

function countSkills(node) {
  if (node.skills) return node.skills.length;
  return (node.children || []).reduce((s, c) => s + countSkills(c), 0);
}

function statusBadge(node) {
  const total = countSkills(node);
  if (total > 0) return `<span class="badge ready">${total} SKILL${total > 1 ? "S" : ""}</span>`;
  if (node.files) return `<span class="badge files">${node.files} FILE${node.files > 1 ? "S" : ""}</span>`;
  return `<span class="badge skeleton">SKELETON</span>`;
}

/* Descending by skill count — empty (skeleton) folders sink to the end. */
function sorted(nodes) {
  return [...nodes].sort((a, b) =>
    countSkills(b) - countSkills(a) || a.name.localeCompare(b.name));
}

function renderNode(node, depth) {
  const isSkill = !!node.skills;
  const det = el("details");
  const sum = el("summary");
  sum.innerHTML = `<span class="node-label">${isSkill ? "📄" : "📁"} ${esc(node.name)}${isSkill ? "" : "/"}</span>
    <span class="node-desc">${esc(node.desc)}</span>
    ${isSkill
      ? `<span class="badge lime">SKILL.md</span>${node.support ? `<span class="badge files">${node.support} FOLDER${node.support > 1 ? "S" : ""}</span>` : ""}`
      : statusBadge(node)}`;
  det.append(sum);
  const body = el("div", "items");
  if (isSkill) {
    node.skills.forEach(s => body.append(el("div", "skill-item",
      `<code title="${esc(s.desc)}">${esc(s.name)}</code> <span>${esc(s.desc)}</span>`)));
  } else if (node.children.length === 0) {
    body.append(el("div", "skill-item", node.files
      ? `<em style="color:var(--dim)">Supporting files (${node.files}) — this folder holds content, not a SKILL.md.</em>`
      : `<em style="color:var(--dim)">Folder ready — skills land here as subfolders appear.</em>`));
  } else {
    sorted(node.children).forEach(c => body.append(renderNode(c, depth + 1)));
  }
  det.append(body);
  const box = el("div", depth <= 2 ? "stack" : "leaf");
  box.append(det);
  return box;
}

function renderCategory(cat) {
  const det = el("details", "category");
  det.open = countSkills(cat) === 0;
  const sum = el("summary");
  sum.innerHTML = `<span class="node-label">${cat.icon} ${esc(cat.name)}/</span>
    <span class="node-desc">${esc(cat.desc)}</span>
    ${cat.badge ? `<span class="badge ${cat.badge === "vendor" ? "skeleton" : "custom"}">${cat.badge.toUpperCase()}</span>` : ""}
    ${statusBadge(cat)}`;
  det.append(sum);
  const body = el("div", "items");
  sorted(cat.children).forEach(c => body.append(renderNode(c, 1)));
  det.append(body);
  return det;
}

async function boot() {
  const res = await fetch("skills.json");
  const data = await res.json();

  document.getElementById("tree-root").append(...sorted(data.categories).map(renderCategory));
  document.querySelector("#tree .section-note").insertAdjacentHTML(
    "afterend",
    `<p class="section-note" style="margin-top:-1rem">📊 ${data.skillCount} skills across ${data.categories.length} categories · catalog regenerates automatically on every push.</p>`);

  document.getElementById("agent-cards").append(...AGENTS.map(a =>
    el("div", "card", `<h3>⚡ ${a.name}</h3><p>Copy or link any skill folder into:</p><code>${a.path}&lt;skill-name&gt;/</code>`)));

  document.getElementById("contributor-cards").append(...data.contributors.map(c =>
    el("div", "card contrib",
      `<div class="avatar">${c.initials}</div>
       <div><h3><a class="inline" href="${c.site || "#"}" target="_blank" rel="noopener">${c.name}</a></h3>
       <div class="role">${c.role}</div>
       <p style="margin-top:.4rem">${c.focus.map(f => `<span class="badge lime">${f}</span>`).join(" ")}</p></div>`)));
}

document.querySelector(".tree-tools").addEventListener("click", e => {
  const open = e.target.dataset.action === "expand";
  document.querySelectorAll(".tree details").forEach(d => (d.open = open));
});

boot();
